;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

 &lt;h1 id=&#34;🧩-Python-程序打包成-EXE-全面教程&#34;&gt;&lt;a href=&#34;#🧩-Python-程序打包成-EXE-全面教程&#34; class=&#34;headerlink&#34; title=&#34;🧩 Python 程序打包成 EXE 全面教程&#34;&gt;&lt;/a&gt;🧩 Python 程序打包成 EXE 全面教程&lt;/h1&gt;&lt;hr&gt;
&lt;h2 id=&#34;📖-一、PyInstaller-简介&#34;&gt;&lt;a href=&#34;#📖-一、PyInstaller-简介&#34; class=&#34;headerlink&#34; title=&#34;📖 一、PyInstaller 简介&#34;&gt;&lt;/a&gt;📖 一、PyInstaller 简介&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;PyInstaller&lt;/strong&gt; 是最常用的 Python 程序打包工具，可以将 &lt;code&gt;.py&lt;/code&gt; 文件及其所有依赖打包成一个可在 Windows 上独立运行的 &lt;code&gt;.exe&lt;/code&gt; 文件。&lt;/p&gt;
&lt;p&gt;特点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;支持所有主流 Python 版本（3.7+）&lt;/li&gt;
&lt;li&gt;无需安装 Python 即可运行打包后的程序&lt;/li&gt;
&lt;li&gt;可打包为单个文件或文件夹结构&lt;/li&gt;
&lt;li&gt;支持添加图标、资源文件、隐藏命令行窗口等&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;⚙️-二、环境准备&#34;&gt;&lt;a href=&#34;#⚙️-二、环境准备&#34; class=&#34;headerlink&#34; title=&#34;⚙️ 二、环境准备&#34;&gt;&lt;/a&gt;⚙️ 二、环境准备&lt;/h2&gt;&lt;h3 id=&#34;1️⃣-检查-Python-环境&#34;&gt;&lt;a href=&#34;#1️⃣-检查-Python-环境&#34; class=&#34;headerlink&#34; title=&#34;1️⃣ 检查 Python 环境&#34;&gt;&lt;/a&gt;1️⃣ 检查 Python 环境&lt;/h3&gt;&lt;p&gt;在命令行输入：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;python &lt;span class=&#34;token parameter variable&#34;&gt;--version&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;输出类似：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;Python &lt;span class=&#34;token number&#34;&gt;3.10&lt;/span&gt;.13&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;确保系统能正确识别 Python。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;2️⃣-安装-PyInstaller&#34;&gt;&lt;a href=&#34;#2️⃣-安装-PyInstaller&#34; class=&#34;headerlink&#34; title=&#34;2️⃣ 安装 PyInstaller&#34;&gt;&lt;/a&gt;2️⃣ 安装 PyInstaller&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; pyinstaller&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;验证安装是否成功：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;--version&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;🧱-三、示例项目结构&#34;&gt;&lt;a href=&#34;#🧱-三、示例项目结构&#34; class=&#34;headerlink&#34; title=&#34;🧱 三、示例项目结构&#34;&gt;&lt;/a&gt;🧱 三、示例项目结构&lt;/h2&gt;&lt;p&gt;假设你的项目如下：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-makefile&#34; data-language=&#34;makefile&#34;&gt;&lt;code class=&#34;language-makefile&#34;&gt;project/
│
├─ main.py              &lt;span class=&#34;token comment&#34;&gt;# 主程序&lt;/span&gt;
├─ config/
│   └─ settings.json    &lt;span class=&#34;token comment&#34;&gt;# 配置文件&lt;/span&gt;
└─ images/
    └─ logo.png         &lt;span class=&#34;token comment&#34;&gt;# 图片资源&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;code&gt;main.py&lt;/code&gt; 示例代码：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; json&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; os&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; sys

&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;resource_path&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token triple-quoted-string string&#34;&gt;&#34;&#34;&#34;获取打包后资源文件的路径&#34;&#34;&#34;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token builtin&#34;&gt;hasattr&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;_MEIPASS&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; os&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;path&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;_MEIPASS&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; os&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;path&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;os&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;path&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;abspath&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;.&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;main&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    config_path &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; resource_path&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;config/settings.json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;with&lt;/span&gt; &lt;span class=&#34;token builtin&#34;&gt;open&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;config_path&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;r&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; encoding&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;utf-8&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;as&lt;/span&gt; f&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        data &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; json&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;load&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;f&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;配置文件内容：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; data&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token builtin&#34;&gt;input&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;按回车退出...&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; __name__ &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;__main__&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    main&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;🚀-四、打包命令详解&#34;&gt;&lt;a href=&#34;#🚀-四、打包命令详解&#34; class=&#34;headerlink&#34; title=&#34;🚀 四、打包命令详解&#34;&gt;&lt;/a&gt;🚀 四、打包命令详解&lt;/h2&gt;&lt;h3 id=&#34;🔹-最简单的打包&#34;&gt;&lt;a href=&#34;#🔹-最简单的打包&#34; class=&#34;headerlink&#34; title=&#34;🔹 最简单的打包&#34;&gt;&lt;/a&gt;🔹 最简单的打包&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;输出目录结构：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;build/      &lt;span class=&#34;token comment&#34;&gt;# 中间构建文件&lt;/span&gt;
dist/       &lt;span class=&#34;token comment&#34;&gt;# 最终生成的可执行文件所在目录&lt;/span&gt;
main.spec   &lt;span class=&#34;token comment&#34;&gt;# PyInstaller 配置文件&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;进入 &lt;code&gt;dist/main/&lt;/code&gt;，可看到：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;main.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔹-打包成单个-exe-文件&#34;&gt;&lt;a href=&#34;#🔹-打包成单个-exe-文件&#34; class=&#34;headerlink&#34; title=&#34;🔹 打包成单个 .exe 文件&#34;&gt;&lt;/a&gt;🔹 打包成单个 &lt;code&gt;.exe&lt;/code&gt; 文件&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;code&gt;-F&lt;/code&gt; 表示 &lt;strong&gt;onefile&lt;/strong&gt; 模式，将所有依赖打包进单个文件中。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出结果：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/main.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔹-添加程序图标&#34;&gt;&lt;a href=&#34;#🔹-添加程序图标&#34; class=&#34;headerlink&#34; title=&#34;🔹 添加程序图标&#34;&gt;&lt;/a&gt;🔹 添加程序图标&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; icon.ico main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;图标文件必须是 &lt;code&gt;.ico&lt;/code&gt; 格式（可用在线转换工具把 &lt;code&gt;.png&lt;/code&gt; 转成 &lt;code&gt;.ico&lt;/code&gt;）。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🔹-去除命令行黑框（GUI-程序用）&#34;&gt;&lt;a href=&#34;#🔹-去除命令行黑框（GUI-程序用）&#34; class=&#34;headerlink&#34; title=&#34;🔹 去除命令行黑框（GUI 程序用）&#34;&gt;&lt;/a&gt;🔹 去除命令行黑框（GUI 程序用）&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;code&gt;-w&lt;/code&gt; 或 &lt;code&gt;--windowed&lt;/code&gt; 表示 &lt;strong&gt;隐藏控制台窗口&lt;/strong&gt;。&lt;br&gt; 用于 PyQt5、Tkinter、wxPython 等图形界面应用。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🔹-自定义生成文件名与输出路径&#34;&gt;&lt;a href=&#34;#🔹-自定义生成文件名与输出路径&#34; class=&#34;headerlink&#34; title=&#34;🔹 自定义生成文件名与输出路径&#34;&gt;&lt;/a&gt;🔹 自定义生成文件名与输出路径&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; app.ico &lt;span class=&#34;token parameter variable&#34;&gt;-n&lt;/span&gt; myApp &lt;span class=&#34;token parameter variable&#34;&gt;--distpath&lt;/span&gt; build_output main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;参数说明：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;-n myApp&lt;/code&gt;：自定义可执行文件名。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;--distpath&lt;/code&gt;：指定输出文件夹（默认是 &lt;code&gt;dist&lt;/code&gt;）。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🔹-打包时包含资源文件&#34;&gt;&lt;a href=&#34;#🔹-打包时包含资源文件&#34; class=&#34;headerlink&#34; title=&#34;🔹 打包时包含资源文件&#34;&gt;&lt;/a&gt;🔹 打包时包含资源文件&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py --add-data &lt;span class=&#34;token string&#34;&gt;&#34;config;config&#34;&lt;/span&gt; --add-data &lt;span class=&#34;token string&#34;&gt;&#34;images;images&#34;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;解释：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;&#34;源路径;目标路径&#34;&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;Windows 用分号 &lt;code&gt;;&lt;/code&gt;，Linux/WSL 用冒号 &lt;code&gt;:&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;打包后：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/main.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;运行时即可自动包含 &lt;code&gt;config/settings.json&lt;/code&gt; 和 &lt;code&gt;images/logo.png&lt;/code&gt;。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧩-五、完整打包命令示例&#34;&gt;&lt;a href=&#34;#🧩-五、完整打包命令示例&#34; class=&#34;headerlink&#34; title=&#34;🧩 五、完整打包命令示例&#34;&gt;&lt;/a&gt;🧩 五、完整打包命令示例&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; app.ico &lt;span class=&#34;token parameter variable&#34;&gt;-n&lt;/span&gt; TrafficMonitor ^
--add-data &lt;span class=&#34;token string&#34;&gt;&#34;config;config&#34;&lt;/span&gt; --add-data &lt;span class=&#34;token string&#34;&gt;&#34;images;images&#34;&lt;/span&gt; ^
main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;运行完毕后：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/TrafficMonitor.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;双击即可运行（无黑框）。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;⚡-六、打包后优化与问题处理&#34;&gt;&lt;a href=&#34;#⚡-六、打包后优化与问题处理&#34; class=&#34;headerlink&#34; title=&#34;⚡ 六、打包后优化与问题处理&#34;&gt;&lt;/a&gt;⚡ 六、打包后优化与问题处理&lt;/h2&gt;&lt;h3 id=&#34;🔸-文件体积太大？&#34;&gt;&lt;a href=&#34;#🔸-文件体积太大？&#34; class=&#34;headerlink&#34; title=&#34;🔸 文件体积太大？&#34;&gt;&lt;/a&gt;🔸 文件体积太大？&lt;/h3&gt;&lt;p&gt;可以用 UPX 压缩：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;# 安装 UPX（可选）&lt;/span&gt;
pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; upx

&lt;span class=&#34;token comment&#34;&gt;# 或手动下载：https://upx.github.io/&lt;/span&gt;
pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py --upx-dir &lt;span class=&#34;token string&#34;&gt;&#34;C:\path&lt;span class=&#34;token entity&#34; title=&#34;\t&#34;&gt;\t&lt;/span&gt;o\upx&#34;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔸-运行时报错：找不到模块&#34;&gt;&lt;a href=&#34;#🔸-运行时报错：找不到模块&#34; class=&#34;headerlink&#34; title=&#34;🔸 运行时报错：找不到模块&#34;&gt;&lt;/a&gt;🔸 运行时报错：找不到模块&lt;/h3&gt;&lt;p&gt;添加隐藏导入模块：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py --hidden-import &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt;模块名&lt;span class=&#34;token operator&#34;&gt;&amp;gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔸-资源文件路径问题&#34;&gt;&lt;a href=&#34;#🔸-资源文件路径问题&#34; class=&#34;headerlink&#34; title=&#34;🔸 资源文件路径问题&#34;&gt;&lt;/a&gt;🔸 资源文件路径问题&lt;/h3&gt;&lt;p&gt;使用下面的函数来获取资源路径（推荐放在开头）：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;import&lt;/span&gt; sys, os

def resource_path&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;:
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; hasattr&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys, &lt;span class=&#34;token string&#34;&gt;&#34;_MEIPASS&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;:
        &lt;span class=&#34;token builtin class-name&#34;&gt;return&lt;/span&gt; os.path.join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys._MEIPASS, relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token builtin class-name&#34;&gt;return&lt;/span&gt; os.path.join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;os.path.abspath&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;.&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;, relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;这样在 &lt;code&gt;.exe&lt;/code&gt; 中也能正确找到资源。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧠-七、使用-spec-文件自定义打包流程&#34;&gt;&lt;a href=&#34;#🧠-七、使用-spec-文件自定义打包流程&#34; class=&#34;headerlink&#34; title=&#34;🧠 七、使用 .spec 文件自定义打包流程&#34;&gt;&lt;/a&gt;🧠 七、使用 &lt;code&gt;.spec&lt;/code&gt; 文件自定义打包流程&lt;/h2&gt;&lt;p&gt;第一次运行 PyInstaller 时会生成 &lt;code&gt;main.spec&lt;/code&gt; 文件，内容类似：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;# main.spec&lt;/span&gt;
a &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Analysis&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;main.py&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;pathex&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;binaries&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;datas&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;config/settings.json&#39;&lt;/span&gt;, &lt;span class=&#34;token string&#34;&gt;&#39;config&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;hiddenimports&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
exe &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; EXE&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
    a.scripts, 
    a.binaries, 
    a.zipfiles, 
    a.datas,
    &lt;span class=&#34;token assign-left variable&#34;&gt;name&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;MyApp&#39;&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;console&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;False,   &lt;span class=&#34;token comment&#34;&gt;# False 表示不显示控制台&lt;/span&gt;
    &lt;span class=&#34;token assign-left variable&#34;&gt;icon&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;app.ico&#39;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;之后可以直接运行：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller main.spec&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;这样不必每次输入长长的命令，适合项目固定打包需求。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🔍-八、完整流程总结&#34;&gt;&lt;a href=&#34;#🔍-八、完整流程总结&#34; class=&#34;headerlink&#34; title=&#34;🔍 八、完整流程总结&#34;&gt;&lt;/a&gt;🔍 八、完整流程总结&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;步骤&lt;/th&gt;
&lt;th&gt;命令&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1️⃣ 安装 PyInstaller&lt;/td&gt;
&lt;td&gt;&lt;code&gt;pip install pyinstaller&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;准备工具&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2️⃣ 编写代码&lt;/td&gt;
&lt;td&gt;&lt;code&gt;main.py&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;确保能独立运行&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3️⃣ 测试运行&lt;/td&gt;
&lt;td&gt;&lt;code&gt;python main.py&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;确认无报错&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4️⃣ 打包命令&lt;/td&gt;
&lt;td&gt;&lt;code&gt;pyinstaller -F -w main.py&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;一键生成 exe&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5️⃣ 添加资源&lt;/td&gt;
&lt;td&gt;&lt;code&gt;--add-data &#34;config;config&#34;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;打包额外文件&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;6️⃣ 添加图标&lt;/td&gt;
&lt;td&gt;&lt;code&gt;-i icon.ico&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;美化图标&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;7️⃣ 生成文件&lt;/td&gt;
&lt;td&gt;查看 &lt;code&gt;dist/&lt;/code&gt; 目录&lt;/td&gt;
&lt;td&gt;直接运行 exe&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;8️⃣ 优化&lt;/td&gt;
&lt;td&gt;使用 UPX 压缩&lt;/td&gt;
&lt;td&gt;减小体积&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧰-九、进阶技巧&#34;&gt;&lt;a href=&#34;#🧰-九、进阶技巧&#34; class=&#34;headerlink&#34; title=&#34;🧰 九、进阶技巧&#34;&gt;&lt;/a&gt;🧰 九、进阶技巧&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;p&gt;批处理打包脚本（保存为 &lt;code&gt;build.bat&lt;/code&gt;）：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;@echo off
&lt;span class=&#34;token builtin class-name&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; 开始打包 &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;
pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; app.ico &lt;span class=&#34;token parameter variable&#34;&gt;-n&lt;/span&gt; MyApp --add-data &lt;span class=&#34;token string&#34;&gt;&#34;config;config&#34;&lt;/span&gt; main.py
&lt;span class=&#34;token builtin class-name&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; 打包完成，生成文件在 dist/MyApp.exe &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;
pause&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;双击 &lt;code&gt;build.bat&lt;/code&gt; 即可一键生成。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;✅-十、示例打包结果&#34;&gt;&lt;a href=&#34;#✅-十、示例打包结果&#34; class=&#34;headerlink&#34; title=&#34;✅ 十、示例打包结果&#34;&gt;&lt;/a&gt;✅ 十、示例打包结果&lt;/h2&gt;&lt;p&gt;成功后会生成：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/
└── MyApp.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;双击即可直接运行，即使目标计算机上&lt;strong&gt;没有安装 Python&lt;/strong&gt;。&lt;/p&gt;

 &lt;h1 id=&#34;WSL2-无法启动、重装-Ubuntu-与执行-configure-sh-权限报错的完整解决方案&#34;&gt;&lt;a href=&#34;#WSL2-无法启动、重装-Ubuntu-与执行-configure-sh-权限报错的完整解决方案&#34; class=&#34;headerlink&#34; title=&#34;WSL2 无法启动、重装 Ubuntu 与执行 configure.sh 权限报错的完整解决方案&#34;&gt;&lt;/a&gt;WSL2 无法启动、重装 Ubuntu 与执行 configure.sh 权限报错的完整解决方案&lt;/h1&gt;&lt;blockquote&gt;
&lt;p&gt;适用系统：Windows 10 / 11&lt;br&gt; 适用发行版：Ubuntu 20.04 / 22.04 / 24.04&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧱-一、问题背景&#34;&gt;&lt;a href=&#34;#🧱-一、问题背景&#34; class=&#34;headerlink&#34; title=&#34;🧱 一、问题背景&#34;&gt;&lt;/a&gt;🧱 一、问题背景&lt;/h2&gt;&lt;p&gt;你在执行：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;-d&lt;/span&gt; Ubuntu-22.04&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;时出现：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;无法将磁盘“C:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Users&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;xxx&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;AppData&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Local&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Packages&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;CanonicalGroupLimited.Ubuntu22.04LTS_79rhkp1fndgsc&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;LocalState&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;ext4.vhdx”附加到 WSL2：系统找不到指定的文件。
错误代码: Wsl/Service/CreateInstance/MountVhd/HCS/ERROR_FILE_NOT_FOUND&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;说明 &lt;strong&gt;WSL 的虚拟磁盘文件 (&lt;code&gt;ext4.vhdx&lt;/code&gt;) 丢失或损坏&lt;/strong&gt;，导致 Ubuntu 无法挂载。&lt;br&gt; 这在系统清理、OneDrive 同步、杀毒误删时非常常见。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🩺-二、第一阶段：确认问题原因&#34;&gt;&lt;a href=&#34;#🩺-二、第一阶段：确认问题原因&#34; class=&#34;headerlink&#34; title=&#34;🩺 二、第一阶段：确认问题原因&#34;&gt;&lt;/a&gt;🩺 二、第一阶段：确认问题原因&lt;/h2&gt;&lt;h3 id=&#34;1️⃣-检查虚拟磁盘是否存在&#34;&gt;&lt;a href=&#34;#1️⃣-检查虚拟磁盘是否存在&#34; class=&#34;headerlink&#34; title=&#34;1️⃣ 检查虚拟磁盘是否存在&#34;&gt;&lt;/a&gt;&lt;strong&gt;1️⃣ 检查虚拟磁盘是否存在&lt;/strong&gt;&lt;/h3&gt;&lt;p&gt;打开资源管理器路径：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;C:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Users&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;xxx&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;AppData&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Local&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Packages&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;CanonicalGroupLimited.Ubuntu22.04LTS_79rhkp1fndgsc&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;LocalState&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;查看是否有文件：ext4.vhdx&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;结果&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;✅ 存在&lt;/td&gt;
&lt;td&gt;文件损坏或被占用&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;❌ 不存在&lt;/td&gt;
&lt;td&gt;文件被删除或路径丢失&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;⚙️-三、第二阶段：解决-ext4-vhdx-丢失问题&#34;&gt;&lt;a href=&#34;#⚙️-三、第二阶段：解决-ext4-vhdx-丢失问题&#34; class=&#34;headerlink&#34; title=&#34;⚙️ 三、第二阶段：解决 ext4.vhdx 丢失问题&#34;&gt;&lt;/a&gt;⚙️ 三、第二阶段：解决 ext4.vhdx 丢失问题&lt;/h2&gt;&lt;h3 id=&#34;方法-1：如果文件存在但打不开&#34;&gt;&lt;a href=&#34;#方法-1：如果文件存在但打不开&#34; class=&#34;headerlink&#34; title=&#34;方法 1：如果文件存在但打不开&#34;&gt;&lt;/a&gt;&lt;strong&gt;方法 1：如果文件存在但打不开&lt;/strong&gt;&lt;/h3&gt;&lt;p&gt;1️⃣ 关闭所有 WSL 服务：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--shutdown&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;2️⃣ 尝试修复：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;diskpart&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;然后依次输入：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;select&lt;/span&gt; vdisk &lt;span class=&#34;token assign-left variable&#34;&gt;file&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;C:\Users\xxx\AppData\Local\Packages\CanonicalGroupLimited.Ubuntu22.04LTS_79rhkp1fndgsc\LocalState&lt;span class=&#34;token entity&#34; title=&#34;\e&#34;&gt;\e&lt;/span&gt;xt4.vhdx&#34;&lt;/span&gt;
attach vdisk &lt;span class=&#34;token builtin class-name&#34;&gt;readonly&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;若可挂载说明文件没坏，否则文件损坏严重。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;方法-2：文件不存在（最常见）&#34;&gt;&lt;a href=&#34;#方法-2：文件不存在（最常见）&#34; class=&#34;headerlink&#34; title=&#34;方法 2：文件不存在（最常见）&#34;&gt;&lt;/a&gt;&lt;strong&gt;方法 2：文件不存在（最常见）&lt;/strong&gt;&lt;/h3&gt;&lt;p&gt;说明 Ubuntu 的根文件系统丢失，只能重装。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🔧-四、第三阶段：卸载旧的-Ubuntu-实例&#34;&gt;&lt;a href=&#34;#🔧-四、第三阶段：卸载旧的-Ubuntu-实例&#34; class=&#34;headerlink&#34; title=&#34;🔧 四、第三阶段：卸载旧的 Ubuntu 实例&#34;&gt;&lt;/a&gt;🔧 四、第三阶段：卸载旧的 Ubuntu 实例&lt;/h2&gt;&lt;h3 id=&#34;1️⃣-停止-WSL&#34;&gt;&lt;a href=&#34;#1️⃣-停止-WSL&#34; class=&#34;headerlink&#34; title=&#34;1️⃣ 停止 WSL&#34;&gt;&lt;/a&gt;&lt;strong&gt;1️⃣ 停止 WSL&lt;/strong&gt;&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--shutdown&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;2️⃣-注销（彻底删除）旧-Ubuntu&#34;&gt;&lt;a href=&#34;#2️⃣-注销（彻底删除）旧-Ubuntu&#34; class=&#34;headerlink&#34; title=&#34;2️⃣ 注销（彻底删除）旧 Ubuntu&#34;&gt;&lt;/a&gt;&lt;strong&gt;2️⃣ 注销（彻底删除）旧 Ubuntu&lt;/strong&gt;&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--unregister&lt;/span&gt; Ubuntu-22.04&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;若不确定发行版名称：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--list&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;3️⃣-删除残留文件夹&#34;&gt;&lt;a href=&#34;#3️⃣-删除残留文件夹&#34; class=&#34;headerlink&#34; title=&#34;3️⃣ 删除残留文件夹&#34;&gt;&lt;/a&gt;&lt;strong&gt;3️⃣ 删除残留文件夹&lt;/strong&gt;&lt;/h3&gt;&lt;p&gt;删除以下目录（若存在）：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;C:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Users&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;xxx&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;AppData&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Local&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Packages&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;CanonicalGroupLimited.Ubuntu22.04LTS_79rhkp1fndgsc&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;🪄-五、第四阶段：重新安装-Ubuntu&#34;&gt;&lt;a href=&#34;#🪄-五、第四阶段：重新安装-Ubuntu&#34; class=&#34;headerlink&#34; title=&#34;🪄 五、第四阶段：重新安装 Ubuntu&#34;&gt;&lt;/a&gt;🪄 五、第四阶段：重新安装 Ubuntu&lt;/h2&gt;&lt;h3 id=&#34;方式一：命令行快速安装（推荐）&#34;&gt;&lt;a href=&#34;#方式一：命令行快速安装（推荐）&#34; class=&#34;headerlink&#34; title=&#34;方式一：命令行快速安装（推荐）&#34;&gt;&lt;/a&gt;&lt;strong&gt;方式一：命令行快速安装（推荐）&lt;/strong&gt;&lt;/h3&gt;&lt;p&gt;在 PowerShell（管理员）运行：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--install&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-d&lt;/span&gt; Ubuntu-22.04&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;如果系统提示 “Installing, this may take a few minutes…&lt;br&gt; WslRegisterDistribution failed with error: 0x80071772”，请继续往下看👇&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧯-六、第五阶段：解决安装时报错-0x80071772&#34;&gt;&lt;a href=&#34;#🧯-六、第五阶段：解决安装时报错-0x80071772&#34; class=&#34;headerlink&#34; title=&#34;🧯 六、第五阶段：解决安装时报错 0x80071772&#34;&gt;&lt;/a&gt;🧯 六、第五阶段：解决安装时报错 &lt;code&gt;0x80071772&lt;/code&gt;&lt;/h2&gt;&lt;p&gt;错误信息：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;WslRegisterDistribution failed with error: 0x80071772
Error: 0x80071772&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;表示系统无法访问 WSL 创建虚拟磁盘文件。&lt;/p&gt;
&lt;h3 id=&#34;解决步骤：&#34;&gt;&lt;a href=&#34;#解决步骤：&#34; class=&#34;headerlink&#34; title=&#34;解决步骤：&#34;&gt;&lt;/a&gt;&lt;strong&gt;解决步骤：&lt;/strong&gt;&lt;/h3&gt;&lt;h4 id=&#34;✅-1️⃣-停止-WSL-服务&#34;&gt;&lt;a href=&#34;#✅-1️⃣-停止-WSL-服务&#34; class=&#34;headerlink&#34; title=&#34;✅ 1️⃣ 停止 WSL 服务&#34;&gt;&lt;/a&gt;✅ 1️⃣ 停止 WSL 服务&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--shutdown&lt;/span&gt;
net stop LxssManager&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;✅-2️⃣-启用必要组件&#34;&gt;&lt;a href=&#34;#✅-2️⃣-启用必要组件&#34; class=&#34;headerlink&#34; title=&#34;✅ 2️⃣ 启用必要组件&#34;&gt;&lt;/a&gt;✅ 2️⃣ 启用必要组件&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dism.exe /online /enable-feature /featurename:VirtualMachinePlatform /all /norestart
dism.exe /online /enable-feature /featurename:Microsoft-Windows-Subsystem-Linux /all /norestart&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;然后重启电脑。&lt;/p&gt;
&lt;h4 id=&#34;✅-3️⃣-检查-AppData-目录权限&#34;&gt;&lt;a href=&#34;#✅-3️⃣-检查-AppData-目录权限&#34; class=&#34;headerlink&#34; title=&#34;✅ 3️⃣ 检查 AppData 目录权限&#34;&gt;&lt;/a&gt;✅ 3️⃣ 检查 AppData 目录权限&lt;/h4&gt;&lt;p&gt;确保：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;C:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Users&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;xxx&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;AppData&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Local&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Packages&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;你拥有“完全控制”权限；&lt;/li&gt;
&lt;li&gt;没有被 OneDrive 云同步（若有云图标 → 右键 “始终保留在此设备上”）。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;✅-4️⃣-重新安装&#34;&gt;&lt;a href=&#34;#✅-4️⃣-重新安装&#34; class=&#34;headerlink&#34; title=&#34;✅ 4️⃣ 重新安装&#34;&gt;&lt;/a&gt;✅ 4️⃣ 重新安装&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--install&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-d&lt;/span&gt; Ubuntu-22.04&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;🚀-七、第六阶段：初始化-Ubuntu-系统&#34;&gt;&lt;a href=&#34;#🚀-七、第六阶段：初始化-Ubuntu-系统&#34; class=&#34;headerlink&#34; title=&#34;🚀 七、第六阶段：初始化 Ubuntu 系统&#34;&gt;&lt;/a&gt;🚀 七、第六阶段：初始化 Ubuntu 系统&lt;/h2&gt;&lt;p&gt;安装完成后首次运行：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;-d&lt;/span&gt; Ubuntu-22.04&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;系统会提示：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;Enter new UNIX username:
New password:&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;设置用户名与密码后即可进入 Ubuntu。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;💾-八、第七阶段：备份与恢复建议&#34;&gt;&lt;a href=&#34;#💾-八、第七阶段：备份与恢复建议&#34; class=&#34;headerlink&#34; title=&#34;💾 八、第七阶段：备份与恢复建议&#34;&gt;&lt;/a&gt;💾 八、第七阶段：备份与恢复建议&lt;/h2&gt;&lt;p&gt;建议你立即备份 WSL 虚拟磁盘，以防下次损坏。&lt;/p&gt;
&lt;h3 id=&#34;✅-导出-WSL-系统镜像：&#34;&gt;&lt;a href=&#34;#✅-导出-WSL-系统镜像：&#34; class=&#34;headerlink&#34; title=&#34;✅ 导出 WSL 系统镜像：&#34;&gt;&lt;/a&gt;✅ 导出 WSL 系统镜像：&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--export&lt;/span&gt; Ubuntu-22.04 D:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Backup&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Ubuntu22.04.tar&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;✅-若以后要恢复：&#34;&gt;&lt;a href=&#34;#✅-若以后要恢复：&#34; class=&#34;headerlink&#34; title=&#34;✅ 若以后要恢复：&#34;&gt;&lt;/a&gt;✅ 若以后要恢复：&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--import&lt;/span&gt; Ubuntu-22.04 D:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;WSL&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Ubuntu22.04 D:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Backup&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Ubuntu22.04.tar&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;⚙️-九、第八阶段：执行-configure-sh-报错-Permission-denied&#34;&gt;&lt;a href=&#34;#⚙️-九、第八阶段：执行-configure-sh-报错-Permission-denied&#34; class=&#34;headerlink&#34; title=&#34;⚙️ 九、第八阶段：执行 configure.sh 报错 Permission denied&#34;&gt;&lt;/a&gt;⚙️ 九、第八阶段：执行 configure.sh 报错 Permission denied&lt;/h2&gt;&lt;p&gt;安装好 Ubuntu 后，你可能遇到：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;-bash: ./configure.sh: Permission denied&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;这通常是因为文件没有执行权限。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🪜-步骤-1：查看文件权限&#34;&gt;&lt;a href=&#34;#🪜-步骤-1：查看文件权限&#34; class=&#34;headerlink&#34; title=&#34;🪜 步骤 1：查看文件权限&#34;&gt;&lt;/a&gt;🪜 步骤 1：查看文件权限&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;ls&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-l&lt;/span&gt; configure.sh&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;若输出为：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;-rw-r--r--&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;说明无执行权限。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🪜-步骤-2：添加执行权限&#34;&gt;&lt;a href=&#34;#🪜-步骤-2：添加执行权限&#34; class=&#34;headerlink&#34; title=&#34;🪜 步骤 2：添加执行权限&#34;&gt;&lt;/a&gt;🪜 步骤 2：添加执行权限&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;chmod&lt;/span&gt; +x configure.sh&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;再次运行：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;./configure.sh&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🧩-特殊情况-1：脚本位于-Windows-目录（如-mnt-c）&#34;&gt;&lt;a href=&#34;#🧩-特殊情况-1：脚本位于-Windows-目录（如-mnt-c）&#34; class=&#34;headerlink&#34; title=&#34;🧩 特殊情况 1：脚本位于 Windows 目录（如 /mnt/c）&#34;&gt;&lt;/a&gt;🧩 特殊情况 1：脚本位于 Windows 目录（如 /mnt/c）&lt;/h3&gt;&lt;p&gt;WSL 无法在 Windows 路径下执行脚本。&lt;/p&gt;
&lt;p&gt;✅ 方法 1：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;cp&lt;/span&gt; /mnt/c/Users/逐梦/Desktop/configure.sh ~/
&lt;span class=&#34;token builtin class-name&#34;&gt;cd&lt;/span&gt; ~
&lt;span class=&#34;token function&#34;&gt;chmod&lt;/span&gt; +x configure.sh
./configure.sh&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;✅ 方法 2：&lt;br&gt; 直接使用 bash 执行（绕过执行权限检查）：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;bash&lt;/span&gt; /mnt/c/Users/逐梦/Desktop/configure.sh&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🧩-特殊情况-2：脚本缺少解释器声明&#34;&gt;&lt;a href=&#34;#🧩-特殊情况-2：脚本缺少解释器声明&#34; class=&#34;headerlink&#34; title=&#34;🧩 特殊情况 2：脚本缺少解释器声明&#34;&gt;&lt;/a&gt;🧩 特殊情况 2：脚本缺少解释器声明&lt;/h3&gt;&lt;p&gt;打开文件：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;head&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-n&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt; configure.sh&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;若第一行不是：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token shebang important&#34;&gt;#!/bin/bash&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;请手动添加，然后保存文件。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;📘-十、知识扩展：理解-Linux-权限&#34;&gt;&lt;a href=&#34;#📘-十、知识扩展：理解-Linux-权限&#34; class=&#34;headerlink&#34; title=&#34;📘 十、知识扩展：理解 Linux 权限&#34;&gt;&lt;/a&gt;📘 十、知识扩展：理解 Linux 权限&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;权限符号&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;r&lt;/td&gt;
&lt;td&gt;可读 (read)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;w&lt;/td&gt;
&lt;td&gt;可写 (write)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;x&lt;/td&gt;
&lt;td&gt;可执行 (execute)&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;例如：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;-rwxr-xr-x&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;表示：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;所有者可读/写/执行；&lt;/li&gt;
&lt;li&gt;组用户和其他人可读/执行。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;✅-十一、总结&#34;&gt;&lt;a href=&#34;#✅-十一、总结&#34; class=&#34;headerlink&#34; title=&#34;✅ 十一、总结&#34;&gt;&lt;/a&gt;✅ 十一、总结&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;阶段&lt;/th&gt;
&lt;th&gt;问题&lt;/th&gt;
&lt;th&gt;解决方法&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1️⃣&lt;/td&gt;
&lt;td&gt;无法附加 VHDX&lt;/td&gt;
&lt;td&gt;文件丢失或损坏&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2️⃣&lt;/td&gt;
&lt;td&gt;卸载 Ubuntu&lt;/td&gt;
&lt;td&gt;&lt;code&gt;wsl --unregister Ubuntu-22.04&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3️⃣&lt;/td&gt;
&lt;td&gt;重装时报错 0x80071772&lt;/td&gt;
&lt;td&gt;启用 WSL 组件、检查权限&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4️⃣&lt;/td&gt;
&lt;td&gt;安装成功但脚本无法执行&lt;/td&gt;
&lt;td&gt;&lt;code&gt;chmod +x configure.sh&lt;/code&gt; 或 &lt;code&gt;bash configure.sh&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5️⃣&lt;/td&gt;
&lt;td&gt;位于 Windows 目录脚本&lt;/td&gt;
&lt;td&gt;复制到 Linux 路径下再运行&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;💡-十二、建议与最佳实践&#34;&gt;&lt;a href=&#34;#💡-十二、建议与最佳实践&#34; class=&#34;headerlink&#34; title=&#34;💡 十二、建议与最佳实践&#34;&gt;&lt;/a&gt;💡 十二、建议与最佳实践&lt;/h2&gt;&lt;p&gt;1️⃣ &lt;strong&gt;定期备份 WSL 实例&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--export&lt;/span&gt; Ubuntu-22.04 D:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Backup&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Ubuntu22.04.tar&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;2️⃣ &lt;strong&gt;不要清理 AppData\Local\Packages\CanonicalGroupLimited…&lt;/strong&gt;&lt;br&gt; 系统清理工具或 OneDrive 会误删 &lt;code&gt;ext4.vhdx&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;3️⃣ &lt;strong&gt;脚本优先放在 Linux 主目录下执行&lt;/strong&gt;&lt;br&gt; 路径：&lt;code&gt;/home/&amp;lt;用户名&amp;gt;/&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;4️⃣ &lt;strong&gt;启用 WSL 自动更新&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;wsl &lt;span class=&#34;token parameter variable&#34;&gt;--update&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

 &lt;h1 id=&#34;XGBoost-参数详解（中文版）&#34;&gt;&lt;a href=&#34;#XGBoost-参数详解（中文版）&#34; class=&#34;headerlink&#34; title=&#34;XGBoost 参数详解（中文版）&#34;&gt;&lt;/a&gt;XGBoost 参数详解（中文版）&lt;/h1&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;原文地址&lt;/strong&gt;：&lt;a href=&#34;https://xgboost.readthedocs.io/en/stable/parameter.html&#34;&gt;https://xgboost.readthedocs.io/en/stable/parameter.html&lt;/a&gt;  &lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;目录&#34;&gt;&lt;a href=&#34;#目录&#34; class=&#34;headerlink&#34; title=&#34;目录&#34;&gt;&lt;/a&gt;目录&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;#1-%E5%8F%82%E6%95%B0%E9%85%8D%E7%BD%AE%E6%96%B9%E5%BC%8F&#34;&gt;1. 参数配置方式&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#2-%E5%8F%82%E6%95%B0%E6%80%BB%E8%A7%88%E8%A1%A8%E6%A0%BC&#34;&gt;2. 参数总览表格&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#3-%E8%AF%A6%E7%BB%86%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E&#34;&gt;3. 详细参数说明&lt;/a&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;#31-%E9%80%9A%E7%94%A8%E5%8F%82%E6%95%B0&#34;&gt;3.1 通用参数&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#32-%E6%A0%91%E6%8F%90%E5%8D%87%E5%99%A8%E5%8F%82%E6%95%B0&#34;&gt;3.2 树提升器参数&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#33-%E7%BA%BF%E6%80%A7%E6%8F%90%E5%8D%87%E5%99%A8%E5%8F%82%E6%95%B0&#34;&gt;3.3 线性提升器参数&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#34-dart-%E6%8F%90%E5%8D%87%E5%99%A8%E5%8F%82%E6%95%B0&#34;&gt;3.4 DART 提升器参数&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#35-%E5%AD%A6%E4%B9%A0%E4%BB%BB%E5%8A%A1%E5%8F%82%E6%95%B0&#34;&gt;3.5 学习任务参数&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#36-%E5%91%BD%E4%BB%A4%E8%A1%8C%E4%B8%93%E7%94%A8%E5%8F%82%E6%95%B0&#34;&gt;3.6 命令行专用参数&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#4-%E5%8F%82%E6%95%B0%E4%BE%9D%E8%B5%96%E5%85%B3%E7%B3%BB%E5%9B%BE&#34;&gt;4. 参数依赖关系图&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#5-%E8%B0%83%E5%8F%82%E5%AE%9E%E6%88%98%E6%8C%87%E5%8D%97&#34;&gt;5. 调参实战指南&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#6-%E5%B8%B8%E8%A7%81%E7%9B%AE%E6%A0%87%E5%87%BD%E6%95%B0%E4%B8%8E%E8%AF%84%E4%BC%B0%E6%8C%87%E6%A0%87%E5%AF%B9%E7%85%A7%E8%A1%A8&#34;&gt;6. 常见目标函数与评估指标对照表&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#7-%E4%B8%AD%E8%8B%B1%E6%96%87%E6%9C%AF%E8%AF%AD%E5%AF%B9%E7%85%A7%E8%A1%A8&#34;&gt;7. 中英文术语对照表&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#8-%E4%BB%A3%E7%A0%81%E7%A4%BA%E4%BE%8B&#34;&gt;8. 代码示例&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;1-参数配置方式&#34;&gt;&lt;a href=&#34;#1-参数配置方式&#34; class=&#34;headerlink&#34; title=&#34;1. 参数配置方式&#34;&gt;&lt;/a&gt;1. 参数配置方式&lt;/h2&gt;&lt;p&gt;XGBoost 支持多种参数传入方式：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;接口&lt;/th&gt;
&lt;th&gt;配置方式&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;xgboost.train&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;字典 &lt;code&gt;param&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;param = {&#39;max_depth&#39;: 6, &#39;eta&#39;: 0.1}&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;XGBClassifier&lt;/code&gt; / &lt;code&gt;XGBRegressor&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;构造函数参数&lt;/td&gt;
&lt;td&gt;&lt;code&gt;XGBClassifier(max_depth=6, eta=0.1)&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;命令行&lt;/td&gt;
&lt;td&gt;&lt;code&gt;key=value&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;xgboost config.conf eta=0.1&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;配置文件&lt;/td&gt;
&lt;td&gt;&lt;code&gt;.conf&lt;/code&gt; 文件&lt;/td&gt;
&lt;td&gt;&lt;code&gt;eta = 0.1&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;推荐&lt;/strong&gt;：使用 Python API 时，优先使用 &lt;code&gt;XGBClassifier&lt;/code&gt; 的 scikit-learn 接口，便于与 &lt;code&gt;GridSearchCV&lt;/code&gt;、&lt;code&gt;Optuna&lt;/code&gt; 等集成。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;2-参数总览表格&#34;&gt;&lt;a href=&#34;#2-参数总览表格&#34; class=&#34;headerlink&#34; title=&#34;2. 参数总览表格&#34;&gt;&lt;/a&gt;2. 参数总览表格&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;别名&lt;/th&gt;
&lt;th&gt;类型&lt;/th&gt;
&lt;th&gt;默认值&lt;/th&gt;
&lt;th&gt;适用提升器&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;通用参数&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;booster&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;gbtree&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;提升器类型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;verbosity&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;silent&lt;/code&gt;（弃用）&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;日志级别&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;validate_parameters&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;bool&lt;/td&gt;
&lt;td&gt;&lt;code&gt;False&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;参数合法性检查&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;nthread&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;None&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;并行线程数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;disable_default_eval_metric&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;禁用默认评估指标&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;树提升器参数&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;eta&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;learning_rate&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.3&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;学习率&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;gamma&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;min_split_loss&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;最小分割损失&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;max_depth&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;6&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;树最大深度&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;min_child_weight&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;子节点最小权重和&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;max_delta_step&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;权重最大步长&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;subsample&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;样本采样比例&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;sampling_method&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;uniform&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;采样方式&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;colsample_bytree&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;特征列采样（按树）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;colsample_bylevel&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;特征列采样（按层）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;colsample_bynode&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;特征列采样（按节点）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;lambda&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;reg_lambda&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;L2 正则化&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;alpha&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;reg_alpha&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;L1 正则化&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;tree_method&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;auto&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;树构建算法&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;sketch_eps&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.03&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;approx&lt;/td&gt;
&lt;td&gt;近似误差&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;scale_pos_weight&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;正负样本权重比&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;grow_policy&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;depthwise&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;hist&lt;/td&gt;
&lt;td&gt;树生长策略&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;max_leaves&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;lossguide&lt;/td&gt;
&lt;td&gt;最大叶子数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;max_bin&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;256&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;hist, gpu_hist&lt;/td&gt;
&lt;td&gt;直方图 bin 数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;predictor&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;cpu_predictor&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;预测器类型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;num_parallel_tree&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gbtree, dart&lt;/td&gt;
&lt;td&gt;每轮并行树数（随机森林）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;线性提升器参数&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;updater&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;shotgun&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;gblinear&lt;/td&gt;
&lt;td&gt;坐标下降策略&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;DART 提升器参数&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;sample_type&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;uniform&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;dart&lt;/td&gt;
&lt;td&gt;dropout 采样类型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;normalize_type&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;tree&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;dart&lt;/td&gt;
&lt;td&gt;归一化方式&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;rate_drop&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;dart&lt;/td&gt;
&lt;td&gt;dropout 比例&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;one_drop&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;dart&lt;/td&gt;
&lt;td&gt;强制至少 dropout 一棵树&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;skip_drop&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;dart&lt;/td&gt;
&lt;td&gt;跳过 dropout 概率&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;学习任务参数&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;objective&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str&lt;/td&gt;
&lt;td&gt;&lt;code&gt;reg:squarederror&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;目标函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;base_score&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;float&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.5&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;初始预测分数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;eval_metric&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;str/list&lt;/td&gt;
&lt;td&gt;自动&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;评估指标&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;seed&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;random_state&lt;/code&gt;（推荐）&lt;/td&gt;
&lt;td&gt;int&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;全部&lt;/td&gt;
&lt;td&gt;随机种子（弃用）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;3-详细参数说明&#34;&gt;&lt;a href=&#34;#3-详细参数说明&#34; class=&#34;headerlink&#34; title=&#34;3. 详细参数说明&#34;&gt;&lt;/a&gt;3. 详细参数说明&lt;/h2&gt;&lt;h3 id=&#34;3-1-通用参数&#34;&gt;&lt;a href=&#34;#3-1-通用参数&#34; class=&#34;headerlink&#34; title=&#34;3.1 通用参数&#34;&gt;&lt;/a&gt;3.1 通用参数&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;详细说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;booster&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选择提升器类型：&lt;br&gt;• &lt;code&gt;gbtree&lt;/code&gt;：树模型（默认，推荐）&lt;br&gt;• &lt;code&gt;gblinear&lt;/code&gt;：线性模型（高维稀疏数据）&lt;br&gt;• &lt;code&gt;dart&lt;/code&gt;：带 dropout 的树模型（防过拟合）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;verbosity&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;日志级别：&lt;br&gt;• &lt;code&gt;0&lt;/code&gt;：静默&lt;br&gt;• &lt;code&gt;1&lt;/code&gt;：警告（默认）&lt;br&gt;• &lt;code&gt;2&lt;/code&gt;：信息&lt;br&gt;• &lt;code&gt;3&lt;/code&gt;：调试（打印每棵树）&lt;br&gt;&lt;strong&gt;注意&lt;/strong&gt;：旧版 &lt;code&gt;silent=1&lt;/code&gt; 表示静默，已弃用&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;validate_parameters&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;是否检查参数合法性。scikit-learn 接口默认 &lt;code&gt;True&lt;/code&gt;。&lt;br&gt;&lt;strong&gt;建议&lt;/strong&gt;：生产环境开启，避免拼写错误&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;nthread&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;并行线程数。&lt;code&gt;None&lt;/code&gt; 使用所有可用核心。&lt;br&gt;&lt;strong&gt;最佳实践&lt;/strong&gt;：显式设置（如 &lt;code&gt;nthread=8&lt;/code&gt;），保证跨机器结果一致&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;disable_default_eval_metric&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt; 表示不使用默认指标（如 RMSE）。适用于自定义指标&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h3 id=&#34;3-2-树提升器参数&#34;&gt;&lt;a href=&#34;#3-2-树提升器参数&#34; class=&#34;headerlink&#34; title=&#34;3.2 树提升器参数&#34;&gt;&lt;/a&gt;3.2 树提升器参数&lt;/h3&gt;&lt;h4 id=&#34;学习率与正则化&#34;&gt;&lt;a href=&#34;#学习率与正则化&#34; class=&#34;headerlink&#34; title=&#34;学习率与正则化&#34;&gt;&lt;/a&gt;学习率与正则化&lt;/h4&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;调参建议&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;eta&lt;/code&gt; (&lt;code&gt;learning_rate&lt;/code&gt;)&lt;/td&gt;
&lt;td&gt;每次提升的步长收缩。范围 &lt;code&gt;[0, 1]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;初始 &lt;code&gt;0.1~0.3&lt;/code&gt;，后期可降至 &lt;code&gt;0.01&lt;/code&gt; + 增加 &lt;code&gt;num_boost_round&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;gamma&lt;/code&gt; (&lt;code&gt;min_split_loss&lt;/code&gt;)&lt;/td&gt;
&lt;td&gt;分割所需最小损失减少。越大越保守&lt;/td&gt;
&lt;td&gt;从 &lt;code&gt;0&lt;/code&gt; 开始，过拟合时增大至 &lt;code&gt;0.1~1&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;lambda&lt;/code&gt; (&lt;code&gt;reg_lambda&lt;/code&gt;)&lt;/td&gt;
&lt;td&gt;L2 正则化（权重平方和）&lt;/td&gt;
&lt;td&gt;默认 &lt;code&gt;1&lt;/code&gt;，过拟合时增大至 &lt;code&gt;5~100&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;alpha&lt;/code&gt; (&lt;code&gt;reg_alpha&lt;/code&gt;)&lt;/td&gt;
&lt;td&gt;L1 正则化（权重绝对值和）&lt;/td&gt;
&lt;td&gt;特征冗余时设 &lt;code&gt;0.1~1&lt;/code&gt;，促进稀疏&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h4 id=&#34;树结构控制&#34;&gt;&lt;a href=&#34;#树结构控制&#34; class=&#34;headerlink&#34; title=&#34;树结构控制&#34;&gt;&lt;/a&gt;树结构控制&lt;/h4&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;典型值&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;max_depth&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;树最大深度。&lt;code&gt;0&lt;/code&gt; 表示无限制&lt;/td&gt;
&lt;td&gt;&lt;code&gt;3~10&lt;/code&gt;，从 &lt;code&gt;6&lt;/code&gt; 开始&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;min_child_weight&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;子节点权重和最小值&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1~10&lt;/code&gt;，大数据集可设 &lt;code&gt;5&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;max_delta_step&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;权重最大步长。不平衡分类时设 &lt;code&gt;1~10&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通常 &lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;max_leaves&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;最大叶子数（与 &lt;code&gt;grow_policy=lossguide&lt;/code&gt; 配合）&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;（无限制）或 &lt;code&gt;32~128&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h4 id=&#34;采样参数（引入随机性）&#34;&gt;&lt;a href=&#34;#采样参数（引入随机性）&#34; class=&#34;headerlink&#34; title=&#34;采样参数（引入随机性）&#34;&gt;&lt;/a&gt;采样参数（引入随机性）&lt;/h4&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;推荐值&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;subsample&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;每棵树采样样本比例&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.6~1.0&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;colsample_bytree&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;每棵树采样特征比例&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.6~1.0&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;colsample_bylevel&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;每层采样特征比例&lt;/td&gt;
&lt;td&gt;通常与 &lt;code&gt;colsample_bytree&lt;/code&gt; 一致&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;colsample_bynode&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;每个节点采样特征比例&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.6~1.0&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;组合建议&lt;/strong&gt;：&lt;code&gt;subsample=0.8, colsample_bytree=0.8&lt;/code&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;树构建算法&#34;&gt;&lt;a href=&#34;#树构建算法&#34; class=&#34;headerlink&#34; title=&#34;树构建算法&#34;&gt;&lt;/a&gt;树构建算法&lt;/h4&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;&lt;code&gt;tree_method&lt;/code&gt;&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;适用场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;auto&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;自动选择（数据 &amp;lt; 10k 用 &lt;code&gt;exact&lt;/code&gt;，否则 &lt;code&gt;hist&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;通用&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;exact&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;精确贪心（遍历所有分割点）&lt;/td&gt;
&lt;td&gt;小数据，追求极致精度&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;approx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;近似贪心（分位数 sketch）&lt;/td&gt;
&lt;td&gt;中等数据&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;hist&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;直方图算法（推荐）&lt;/td&gt;
&lt;td&gt;大数据，速度快&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;gpu_hist&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;GPU 直方图&lt;/td&gt;
&lt;td&gt;GPU 环境，超大数据&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;推荐&lt;/strong&gt;：&lt;code&gt;tree_method=&#39;hist&#39;&lt;/code&gt;（CPU）或 &lt;code&gt;&#39;gpu_hist&#39;&lt;/code&gt;（GPU）&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;3-3-线性提升器参数&#34;&gt;&lt;a href=&#34;#3-3-线性提升器参数&#34; class=&#34;headerlink&#34; title=&#34;3.3 线性提升器参数&#34;&gt;&lt;/a&gt;3.3 线性提升器参数&lt;/h3&gt;&lt;p&gt;适用于 &lt;code&gt;booster=gblinear&lt;/code&gt;：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;updater&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;shotgun&lt;/code&gt;（随机坐标下降，适合稀疏数据）&lt;br&gt;&lt;code&gt;coord_descent&lt;/code&gt;（全坐标下降，适合稠密数据）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;lambda&lt;/code&gt;, &lt;code&gt;alpha&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;同树模型，控制权重正则化&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;适用场景&lt;/strong&gt;：文本分类（TF-IDF）、推荐系统（高维稀疏特征）&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;3-4-DART-提升器参数&#34;&gt;&lt;a href=&#34;#3-4-DART-提升器参数&#34; class=&#34;headerlink&#34; title=&#34;3.4 DART 提升器参数&#34;&gt;&lt;/a&gt;3.4 DART 提升器参数&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;推荐&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;rate_drop&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;每轮 dropout 树比例&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.1~0.3&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;one_drop&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt; 表示至少 dropout 一棵树&lt;/td&gt;
&lt;td&gt;配合 &lt;code&gt;rate_drop&amp;gt;0&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;skip_drop&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;跳过 dropout 的概率（动态控制）&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0.2~0.5&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;normalize_type&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;tree&lt;/code&gt;（每树归一化）或 &lt;code&gt;forest&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通常 &lt;code&gt;tree&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;使用场景&lt;/strong&gt;：深度树 + 易过拟合任务&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;3-5-学习任务参数&#34;&gt;&lt;a href=&#34;#3-5-学习任务参数&#34; class=&#34;headerlink&#34; title=&#34;3.5 学习任务参数&#34;&gt;&lt;/a&gt;3.5 学习任务参数&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;objective&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;目标函数&lt;/td&gt;
&lt;td&gt;&lt;code&gt;binary:logistic&lt;/code&gt;, &lt;code&gt;reg:squarederror&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;base_score&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;初始预测值&lt;/td&gt;
&lt;td&gt;分类 &lt;code&gt;0.5&lt;/code&gt;，回归 &lt;code&gt;y.mean()&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;eval_metric&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;评估指标&lt;/td&gt;
&lt;td&gt;&lt;code&gt;[&#39;auc&#39;, &#39;logloss&#39;]&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;scale_pos_weight&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;正负样本权重比&lt;/td&gt;
&lt;td&gt;&lt;code&gt;sum(neg) / sum(pos)&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h3 id=&#34;3-6-命令行专用参数&#34;&gt;&lt;a href=&#34;#3-6-命令行专用参数&#34; class=&#34;headerlink&#34; title=&#34;3.6 命令行专用参数&#34;&gt;&lt;/a&gt;3.6 命令行专用参数&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;num_round&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;提升轮数（必需）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;data&lt;/code&gt; / &lt;code&gt;test:data&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;数据路径&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;watchlist&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;监控集：&lt;code&gt;train:data/train.txt,val:data/val.txt&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;model_in&lt;/code&gt; / &lt;code&gt;model_out&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;模型加载/保存&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;4-参数依赖关系图&#34;&gt;&lt;a href=&#34;#4-参数依赖关系图&#34; class=&#34;headerlink&#34; title=&#34;4. 参数依赖关系图&#34;&gt;&lt;/a&gt;4. 参数依赖关系图&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-mermaid&#34; data-language=&#34;mermaid&#34;&gt;&lt;code class=&#34;language-mermaid&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;graph&lt;/span&gt; TD
    A&lt;span class=&#34;token text string&#34;&gt;[booster]&lt;/span&gt; &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; B&lt;span class=&#34;token text string&#34;&gt;[gbtree]&lt;/span&gt;
    A &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; C&lt;span class=&#34;token text string&#34;&gt;[gblinear]&lt;/span&gt;
    A &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; D&lt;span class=&#34;token text string&#34;&gt;[dart]&lt;/span&gt;
    B &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; E&lt;span class=&#34;token text string&#34;&gt;[tree_method]&lt;/span&gt;
    E &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; F&lt;span class=&#34;token text string&#34;&gt;[hist]&lt;/span&gt;
    E &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; G&lt;span class=&#34;token text string&#34;&gt;[gpu_hist]&lt;/span&gt;
    F &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; H&lt;span class=&#34;token text string&#34;&gt;[max_bin]&lt;/span&gt;
    B &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; I&lt;span class=&#34;token text string&#34;&gt;[subsample]&lt;/span&gt;
    B &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; J&lt;span class=&#34;token text string&#34;&gt;[colsample_bytree]&lt;/span&gt;
    B &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; K&lt;span class=&#34;token text string&#34;&gt;[max_depth]&lt;/span&gt;
    D &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; L&lt;span class=&#34;token text string&#34;&gt;[rate_drop]&lt;/span&gt;
    A &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; M&lt;span class=&#34;token text string&#34;&gt;[objective]&lt;/span&gt;
    M &lt;span class=&#34;token arrow operator&#34;&gt;--&amp;gt;&lt;/span&gt; N&lt;span class=&#34;token text string&#34;&gt;[eval_metric]&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;5-调参实战指南（推荐流程）&#34;&gt;&lt;a href=&#34;#5-调参实战指南（推荐流程）&#34; class=&#34;headerlink&#34; title=&#34;5. 调参实战指南（推荐流程）&#34;&gt;&lt;/a&gt;5. 调参实战指南（推荐流程）&lt;/h2&gt;&lt;p&gt;text&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;1. 固定学习率：eta = 0.1
2. 调树复杂度：
   - max_depth: 3~10
   - min_child_weight: 1~10
   - gamma: 0~1
3. 调正则化：
   - lambda: 1~100
   - alpha: 0~1
4. 调采样：
   - subsample: 0.6~1.0
   - colsample_bytree: 0.6~1.0
5. 降低 eta（如 0.05）+ 增加 num_boost_round
6. 使用早停（early_stopping_rounds=50）&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;6-常见目标函数与评估指标对照表&#34;&gt;&lt;a href=&#34;#6-常见目标函数与评估指标对照表&#34; class=&#34;headerlink&#34; title=&#34;6. 常见目标函数与评估指标对照表&#34;&gt;&lt;/a&gt;6. 常见目标函数与评估指标对照表&lt;/h2&gt;&lt;table&gt;
