&lt;td&gt;多分类&lt;/td&gt;
&lt;td&gt;multi:softmax&lt;/td&gt;
&lt;td&gt;merror&lt;/td&gt;
&lt;td&gt;merror, mlogloss&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;多分类（概率）&lt;/td&gt;
&lt;td&gt;multi:softprob&lt;/td&gt;
&lt;td&gt;merror&lt;/td&gt;
&lt;td&gt;同上&lt;/td&gt;
